export type notebookTemplatesLogicType = MakeLogicType<
    notebookTemplatesLogicValues,
    notebookTemplatesLogicActions,
    Record<string, any>,
    notebookTemplatesLogicMeta
>

export const notebookTemplatesLogic = kea<notebookTemplatesLogicType>([
    path(['scenes', 'notebooks', 'NotebookTemplates', 'notebookTemplatesLogic']),
    connect(() => ({
        values: [notebooksModel, ['notebookTemplates']],
        actions: [notebooksModel, ['createNotebook', 'createNotebookSuccess', 'createNotebookFailure']],
    })),
    actions({
        createNotebookFromTemplate: (shortId: string) => ({ shortId }),
    }),
    reducers({
        creatingTemplate: [
            null as string | null,
            {
                createNotebookFromTemplate: (_, { shortId }) => shortId,
                createNotebookSuccess: () => null,
                createNotebookFailure: () => null,
            },
        ],
    }),
    selectors({
        // The model owns the list so a future remote-template loader flows through here; the local
        // registry supplies the card copy and markdown the NotebookType shape does not carry.
        templates: [
            (s) => [s.notebookTemplates],
            (notebookTemplates: NotebookType[]): NotebookTemplate[] =>
                notebookTemplates
                    .map((notebook) => NOTEBOOK_TEMPLATES.find((template) => template.short_id === notebook.short_id))
                    .filter((template): template is NotebookTemplate => !!template),
        ],
    }),
    listeners(({ actions, values }) => ({
        createNotebookFromTemplate: ({ shortId }) => {
            const template = values.templates.find((candidate) => candidate.short_id === shortId)
            if (!template) {
                return
            }

            actions.createNotebook(
                NotebookTarget.Scene,
                template.title,
                undefined,
                undefined,
                undefined,
                template.markdown,
                template.short_id
            )
        },
    })),
])
